        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Il mondo è un bel libro, ma poco serve a chi non lo sa leggere.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "La gola è un vizio che non finisce mai, ed è quel vizio che cresce sempre quanto più l'uomo invecchia.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Le bugìe sono per natura così feconde, che una ne suole partorir cento.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Tutti cercan di fare quello che fanno gli altri. Una volta correva l'acquavite, adesso è in voga il caffè.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Se conoscete che la persona che amate meriti l'amor vostro, disponete l'animo a sofferir qualche cosa.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Dalle donne qualche cosa convien soffrire; quando si sa specialmente che una donna vuol bene, non serve il sofisticare, non convien pesar le parole colla bilancia dell'oro, e guardare i moscherini col microscopio per ingrandirli.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "La sincerità non vi è oro che la paghi.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Tutto il mio piacere consiste in vedermi servita, vagheggiata, adorata. Questa è la mia debolezza, e questa è la debolezza di quasi tutte le donne.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Come l'appetito rende saporite le vivande!", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Quante persone non vi sono di modi soavi e di pulitissimo tratto, che mutano poi tono, carattere ed anche aspetto, poste a un tavolino da giuoco? Un uomo generoso divien talvolta furibondo, anche per una perdita leggiera. La cagione non è, egli dice, la perdita del danaro, ma bensì l'amor proprio.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Non bisogna che le padrone di casa siano le prime ad incominciar la partita, lasciando accomodar gli altri nella maniera che loro piace: ciò è avvenuto più d'una volta sotto i miei occhi, ed io medesimo poi sono stato testimone delle lagnanze di quelli che si son creduti mal collocati.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Sento intorno a me vociare terni, quaderne, cinquine, mentre io non ho altro che estratti, e qualche ambo; divento giuocatore senza saperlo; me la prendo con quelli che vincono, perchè la loro vincita deve per necessità accrescere la mia perdita, onde il mio amor proprio ne resta offeso, non meno che l'interesse della mia borsa.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Il mondo è bel, perch'è di vari umori. Vari sono degli uomini i capricci: A chi piacciono l'armi, a chi gli amori, A chi piaccion le torte, a chi i pasticci. De' gusti disputar cosa è fallace; Non è bel quel ch'e bel, ma quel che piace.", Author = "Carlo Goldoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Goldoni", Text = "Sì, vi vuol coraggio: bisogna fare un'eroica risoluzione. L'amicizia ha da prevalere, e alla vera amicizia bisogna sagrificare le proprie passioni, le proprie soddisfazioni, e ancora la vita stessa, se è necessario.", Author = "Carlo Goldoni" },
        };
